+namespace CheckoutPricing.Domain;
+
+internal sealed class PromoCode
+{
+    private const int WelcomeCents = 500;
+    private const int SummerCapCents = 1_500;
+    private const int SummerPercent = 10;
+
+    private static readonly PromoCode None = new(_ => 0);
+    private static readonly PromoCode Welcome5 = new(_ => WelcomeCents);
+    private static readonly PromoCode Summer10 = new(
+        remainingCents => Math.Min(remainingCents * SummerPercent / 100, SummerCapCents));
+
+    private readonly Func<int, int> discountOnRemaining;
+
+    private PromoCode(Func<int, int> discountOnRemaining) =>
+        this.discountOnRemaining = discountOnRemaining;
+
+    public static PromoCode From(string? code) => code?.ToUpperInvariant() switch
+    {
+        "WELCOME5" => Welcome5,
+        "SUMMER10" => Summer10,
+        _ => None
+    };
+
+    public int DiscountCents(int remainingCents) => discountOnRemaining(remainingCents);
+}

